102:    inline uint32_t swap_uint32( uint32_t val )
103:    {
104:       val = ( ( val << 8 ) & 0xFF00FF00 ) | ( ( val >> 8 ) & 0xFF00FF );
105: 
106:       return ( val << 16 ) | ( val >> 16 );
107:    }
108: 
109:    /// Calc CRC32C of given data
110:    uint32_t checksum( char *buf, size_t size )
111:    {
112:       static const CRC::Parameters<crcpp_uint32, 32> sCRCParams{ 0x1EDC6F41, 0xFFFFFFFF, 0xFFFFFFFF,
113:                                                                  true, true };
114: 
115:       static const CRC::Table<crcpp_uint32, 32> sCRCTable = sCRCParams.MakeTable();
116: 
117:       auto crc = CRC::Calculate<crcpp_uint32, 32>( buf, size, sCRCTable );
118: 
119:       // (Andy) I don't understand why we need to swap bytes here
120:       crc = swap_uint32( crc );
121: 
122:       return crc;
123:    }
