493: uint64_t CheckedFile::lseek64( int64_t offset, int whence )
494: {
495:    if ( ( fd_ < 0 ) && ( bufView_ != nullptr ) )
496:    {
497:       const auto uoffset = static_cast<uint64_t>( offset );
498: 
499:       if ( bufView_->seek( uoffset, whence ) )
500:       {
501:          return bufView_->pos();
502:       }
503: 
504:       throw E57_EXCEPTION2( ErrorSeekFailed, "fileName=" + fileName_ +
505:                                                 " offset=" + toString( offset ) +
506:                                                 " whence=" + toString( whence ) );
507:    }
508: 
509: #if defined( _WIN32 )
510:    __int64 result = _lseeki64( fd_, offset, whence );
511: #elif defined( __linux__ ) || defined( __EMSCRIPTEN__ )
512:    int64_t result = ::lseek64( fd_, offset, whence );
513: #elif defined( __APPLE__ ) || defined( __BSD )
514:    int64_t result = ::lseek( fd_, offset, whence );
515: #else
516: #error "no supported OS platform defined"
517: #endif
518: 
519:    if ( result < 0 )
520:    {
521:       throw E57_EXCEPTION2( ErrorSeekFailed,
522:                             "fileName=" + fileName_ + " offset=" + toString( offset ) +
523:                                " whence=" + toString( whence ) + " result=" + toString( result ) );
524:    }
525: 
526:    return static_cast<uint64_t>( result );
527: }
