323: void E57XmlParser::startElement( const XMLCh *const uri, const XMLCh *const localName,
324:                                  const XMLCh *const qName, const Attributes &attributes )
325: {
326: #ifdef E57_VERBOSE
327:    std::cout << "startElement" << std::endl;
328:    std::cout << space( 2 ) << "URI:       " << toUString( uri ) << std::endl;
329:    std::cout << space( 2 ) << "localName: " << toUString( localName ) << std::endl;
330:    std::cout << space( 2 ) << "qName:     " << toUString( qName ) << std::endl;
331: 
332:    for ( size_t i = 0; i < attributes.getLength(); i++ )
333:    {
334:       std::cout << space( 2 ) << "Attribute[" << i << "]" << std::endl;
335:       std::cout << space( 4 ) << "URI:       " << toUString( attributes.getURI( i ) ) << std::endl;
336:       std::cout << space( 4 ) << "localName: " << toUString( attributes.getLocalName( i ) )
337:                 << std::endl;
338:       std::cout << space( 4 ) << "qName:     " << toUString( attributes.getQName( i ) )
339:                 << std::endl;
340:       std::cout << space( 4 ) << "value:     " << toUString( attributes.getValue( i ) )
341:                 << std::endl;
342:    }
343: #endif
344:    // Get Type attribute
345:    ustring node_type = lookupAttribute( attributes, att_type );
346: 
347:    //??? check to make sure not in primitive type (can only nest inside compound types).
348: 
349:    ParseInfo pi;
350: 
351:    if ( node_type == "Integer" )
352:    {
353: #ifdef E57_VERBOSE
354:       std::cout << "got a Integer" << std::endl;
355: #endif
356:       //??? check validity of numeric strings
357:       pi.nodeType = TypeInteger;
358: 
359:       if ( isAttributeDefined( attributes, att_minimum ) )
360:       {
361:          ustring minimum_str = lookupAttribute( attributes, att_minimum );
362: 
363:          pi.minimum = convertStrToLL( minimum_str );
364:       }
365:       else
366:       {
367:          // Not defined defined in XML, so defaults to E57_INT64_MIN
368:          pi.minimum = INT64_MIN;
369:       }
370: 
371:       if ( isAttributeDefined( attributes, att_maximum ) )
372:       {
373:          ustring maximum_str = lookupAttribute( attributes, att_maximum );
374: 
375:          pi.maximum = convertStrToLL( maximum_str );
376:       }
377:       else
378:       {
379:          // Not defined defined in XML, so defaults to E57_INT64_MAX
380:          pi.maximum = INT64_MAX;
381:       }
382: 
383:       stack_.push( pi );
384:    }
385:    else if ( node_type == "ScaledInteger" )
386:    {
387: #ifdef E57_VERBOSE
388:       std::cout << "got a ScaledInteger" << std::endl;
389: #endif
390:       pi.nodeType = TypeScaledInteger;
391: 
392:       //??? check validity of numeric strings
393:       if ( isAttributeDefined( attributes, att_minimum ) )
394:       {
395:          ustring minimum_str = lookupAttribute( attributes, att_minimum );
396: 
397:          pi.minimum = convertStrToLL( minimum_str );
398:       }
399:       else
400:       {
401:          // Not defined defined in XML, so defaults to E57_INT64_MIN
402:          pi.minimum = INT64_MIN;
403:       }
404: 
405:       if ( isAttributeDefined( attributes, att_maximum ) )
406:       {
407:          ustring maximum_str = lookupAttribute( attributes, att_maximum );
408: 
409:          pi.maximum = convertStrToLL( maximum_str );
410:       }
411:       else
412:       {
413:          // Not defined defined in XML, so defaults to E57_INT64_MAX
414:          pi.maximum = INT64_MAX;
415:       }
416: 
417:       if ( isAttributeDefined( attributes, att_scale ) )
418:       {
419:          ustring scale_str = lookupAttribute( attributes, att_scale );
420:          pi.scale = strToDouble( scale_str ); //??? use exact rounding library
421:       }
422:       else
423:       {
424:          // Not defined defined in XML, so defaults to 1.0
425:          pi.scale = 1.0;
426:       }
427: 
428:       if ( isAttributeDefined( attributes, att_offset ) )
429:       {
430:          ustring offset_str = lookupAttribute( attributes, att_offset );
431:          pi.offset = strToDouble( offset_str ); //??? use exact rounding library
432:       }
433:       else
434:       {
435:          // Not defined defined in XML, so defaults to 0.0
436:          pi.offset = 0.0;
437:       }
438: 
439:       stack_.push( pi );
440:    }
441:    else if ( node_type == "Float" )
442:    {
443: #ifdef E57_VERBOSE
444:       std::cout << "got a Float" << std::endl;
445: #endif
446:       pi.nodeType = TypeFloat;
447: 
448:       if ( isAttributeDefined( attributes, att_precision ) )
449:       {
450:          ustring precision_str = lookupAttribute( attributes, att_precision );
451:          if ( precision_str == "single" )
452:          {
453:             pi.precision = PrecisionSingle;
454:          }
455:          else if ( precision_str == "double" )
456:          {
457:             pi.precision = PrecisionDouble;
458:          }
459:          else
460:          {
461:             throw E57_EXCEPTION2( ErrorBadXMLFormat, "precisionString=" + precision_str +
462:                                                         " fileName=" + imf_->fileName() +
463:                                                         " uri=" + toUString( uri ) +
464:                                                         " localName=" + toUString( localName ) +
465:                                                         " qName=" + toUString( qName ) );
466:          }
467:       }
468:       else
469:       {
470:          // Not defined defined in XML, so defaults to double
471:          pi.precision = PrecisionDouble;
472:       }
473: 
474:       if ( isAttributeDefined( attributes, att_minimum ) )
475:       {
476:          ustring minimum_str = lookupAttribute( attributes, att_minimum );
477:          pi.floatMinimum = strToDouble( minimum_str ); //??? use exact rounding library
478:       }
479:       else
480:       {
481:          // Not defined defined in XML, so defaults to E57_FLOAT_MIN or E57_DOUBLE_MIN
482:          if ( pi.precision == PrecisionSingle )
483:          {
484:             pi.floatMinimum = FLOAT_MIN;
485:          }
486:          else
487:          {
488:             pi.floatMinimum = DOUBLE_MIN;
489:          }
490:       }
491: 
492:       if ( isAttributeDefined( attributes, att_maximum ) )
493:       {
494:          ustring maximum_str = lookupAttribute( attributes, att_maximum );
495:          pi.floatMaximum = strToDouble( maximum_str ); //??? use exact rounding library
496:       }
497:       else
498:       {
499:          // Not defined defined in XML, so defaults to FLOAT_MAX or DOUBLE_MAX
500:          if ( pi.precision == PrecisionSingle )
501:          {
502:             pi.floatMaximum = FLOAT_MAX;
503:          }
504:          else
505:          {
506:             pi.floatMaximum = DOUBLE_MAX;
507:          }
508:       }
509: 
510:       stack_.push( pi );
511:    }
512:    else if ( node_type == "String" )
513:    {
514: #ifdef E57_VERBOSE
515:       std::cout << "got a String" << std::endl;
516: #endif
517:       pi.nodeType = TypeString;
518: 
519:       stack_.push( pi );
520:    }
521:    else if ( node_type == "Blob" )
522:    {
523: #ifdef E57_VERBOSE
524:       std::cout << "got a Blob" << std::endl;
525: #endif
526:       pi.nodeType = TypeBlob;
527: 
528:       //??? check validity of numeric strings
529: 
530:       // fileOffset is required to be defined
531:       ustring fileOffset_str = lookupAttribute( attributes, att_fileOffset );
532: 
533:       pi.fileOffset = convertStrToLL( fileOffset_str );
534: 
535:       // length is required to be defined
536:       ustring length_str = lookupAttribute( attributes, att_length );
537: 
538:       pi.length = convertStrToLL( length_str );
539: 
540:       stack_.push( pi );
541:    }
542:    else if ( node_type == "Structure" )
543:    {
544: #ifdef E57_VERBOSE
545:       std::cout << "got a Structure" << std::endl;
546: #endif
547:       pi.nodeType = TypeStructure;
548: 
549:       // Read name space decls, if e57Root element
550:       if ( toUString( localName ) == "e57Root" )
551:       {
552:          // Search attributes for namespace declarations (only allowed in E57Root structure)
553:          bool gotDefault = false;
554:          for ( size_t i = 0; i < attributes.getLength(); i++ )
555:          {
556:             // Check if declaring the default namespace
557:             if ( toUString( attributes.getQName( i ) ) == "xmlns" )
558:             {
559: #ifdef E57_VERBOSE
560:                std::cout << "declared default namespace, URI="
561:                          << toUString( attributes.getValue( i ) ) << std::endl;
562: #endif
563:                imf_->extensionsAdd( "", toUString( attributes.getValue( i ) ) );
564:                gotDefault = true;
565:             }
566: 
567:             // Check if declaring a namespace
568:             if ( toUString( attributes.getURI( i ) ) == "http://www.w3.org/2000/xmlns/" )
569:             {
570: #ifdef E57_VERBOSE
571:                std::cout << "declared extension, prefix="
572:                          << toUString( attributes.getLocalName( i ) )
573:                          << " URI=" << toUString( attributes.getValue( i ) ) << std::endl;
574: #endif
575:                imf_->extensionsAdd( toUString( attributes.getLocalName( i ) ),
576:                                     toUString( attributes.getValue( i ) ) );
577:             }
578:          }
579: 
580:          // If didn't declare a default namespace, have error
581:          if ( !gotDefault )
582:          {
583:             throw E57_EXCEPTION2( ErrorBadXMLFormat, "fileName=" + imf_->fileName() +
584:                                                         " uri=" + toUString( uri ) +
585:                                                         " localName=" + toUString( localName ) +
586:                                                         " qName=" + toUString( qName ) );
587:          }
588:       }
589: 
590:       // Create container now, so can hold children
591:       std::shared_ptr<StructureNodeImpl> s_ni( new StructureNodeImpl( imf_ ) );
592:       pi.container_ni = s_ni;
593: 
594:       // After have Structure, check again if E57Root, if so mark attached so all children will be
595:       // attached when added
596:       if ( toUString( localName ) == "e57Root" )
597:       {
598:          s_ni->setAttachedRecursive();
599:       }
600: 
601:       stack_.push( pi );
602:    }
603:    else if ( node_type == "Vector" )
604:    {
605: #ifdef E57_VERBOSE
606:       std::cout << "got a Vector" << std::endl;
607: #endif
608:       pi.nodeType = TypeVector;
609: 
610:       if ( isAttributeDefined( attributes, att_allowHeterogeneousChildren ) )
611:       {
612:          ustring allowHetero_str = lookupAttribute( attributes, att_allowHeterogeneousChildren );
613: 
614:          int64_t i64 = convertStrToLL( allowHetero_str );
615: 
616:          if ( i64 == 0 )
617:          {
618:             pi.allowHeterogeneousChildren = false;
619:          }
620:          else if ( i64 == 1 )
621:          {
622:             pi.allowHeterogeneousChildren = true;
623:          }
624:          else
625:          {
626:             throw E57_EXCEPTION2( ErrorBadXMLFormat,
627:                                   "allowHeterogeneousChildren=" + toString( i64 ) +
628:                                      "fileName=" + imf_->fileName() + " uri=" + toUString( uri ) +
629:                                      " localName=" + toUString( localName ) +
630:                                      " qName=" + toUString( qName ) );
631:          }
632:       }
633:       else
634:       {
635:          // Not defined defined in XML, so defaults to false
636:          pi.allowHeterogeneousChildren = false;
637:       }
638: 
639:       // Create container now, so can hold children
640:       std::shared_ptr<VectorNodeImpl> v_ni(
641:          new VectorNodeImpl( imf_, pi.allowHeterogeneousChildren ) );
642:       pi.container_ni = v_ni;
643: 
644:       stack_.push( pi );
645:    }
646:    else if ( node_type == "CompressedVector" )
647:    {
648: #ifdef E57_VERBOSE
649:       std::cout << "got a CompressedVector" << std::endl;
650: #endif
651:       pi.nodeType = TypeCompressedVector;
652: 
653:       // fileOffset is required to be defined
654:       ustring fileOffset_str = lookupAttribute( attributes, att_fileOffset );
655: 
656:       pi.fileOffset = convertStrToLL( fileOffset_str );
657: 
658:       // recordCount is required to be defined
659:       ustring recordCount_str = lookupAttribute( attributes, att_recordCount );
660: 
661:       pi.recordCount = convertStrToLL( recordCount_str );
662: 
663:       // Create container now, so can hold children
664:       std::shared_ptr<CompressedVectorNodeImpl> cv_ni( new CompressedVectorNodeImpl( imf_ ) );
665:       cv_ni->setRecordCount( pi.recordCount );
666:       cv_ni->setBinarySectionLogicalStart(
667:          imf_->file_->physicalToLogical( pi.fileOffset ) ); //??? what if file_ is NULL?
668:       pi.container_ni = cv_ni;
669: 
670:       stack_.push( pi );
671:    }
672:    else
673:    {
674:       throw E57_EXCEPTION2( ErrorBadXMLFormat,
675:                             "nodeType=" + node_type + " fileName=" + imf_->fileName() +
676:                                " uri=" + toUString( uri ) + " localName=" + toUString( localName ) +
677:                                " qName=" + toUString( qName ) );
678:    }
679: #ifdef E57_VERBOSE
680:    pi.dump( 4 );
681: #endif
682: }
