684: void E57XmlParser::endElement( const XMLCh *const uri, const XMLCh *const localName,
685:                                const XMLCh *const qName )
686: {
687: #ifdef E57_VERBOSE
688:    std::cout << "endElement" << std::endl;
689: #endif
690: 
691:    // Pop the node that just ended
692:    ParseInfo pi = stack_.top(); //??? really want to make a copy here?
693:    stack_.pop();
694: #ifdef E57_VERBOSE
695:    pi.dump( 4 );
696: #endif
697: 
698:    // We should now have all the info we need to create the node
699:    NodeImplSharedPtr current_ni;
700: 
701:    switch ( pi.nodeType )
702:    {
703:       case TypeStructure:
704:       case TypeVector:
705:          current_ni = pi.container_ni;
706:          break;
707:       case TypeCompressedVector:
708:       {
709:          // Verify that both prototype and codecs child elements were defined
710:          // ???
711:          current_ni = pi.container_ni;
712:       }
713:       break;
714:       case TypeInteger:
715:       {
716:          // Convert child text (if any) to value, else default to 0
717:          int64_t intValue = 0;
718:          bool foundValue = false;
719: 
720:          if ( pi.childText.length() > 0 )
721:          {
722:             intValue = convertStrToLL( pi.childText );
723:             foundValue = true;
724:          }
725: 
726:          std::shared_ptr<IntegerNodeImpl> i_ni(
727:             new IntegerNodeImpl( imf_, intValue, pi.minimum, pi.maximum ) );
728: 
729:          if ( foundValue )
730:          {
731:             i_ni->validateValue();
732:          }
733: 
734:          current_ni = i_ni;
735:       }
736:       break;
737:       case TypeScaledInteger:
738:       {
739:          // Convert child text (if any) to value, else default to 0
740:          int64_t intValue = 0;
741:          bool foundValue = false;
742: 
743:          if ( pi.childText.length() > 0 )
744:          {
745:             intValue = convertStrToLL( pi.childText );
746:             foundValue = true;
747:          }
748: 
749:          std::shared_ptr<ScaledIntegerNodeImpl> si_ni( new ScaledIntegerNodeImpl(
750:             imf_, intValue, pi.minimum, pi.maximum, pi.scale, pi.offset ) );
751: 
752:          if ( foundValue )
753:          {
754:             si_ni->validateValue();
755:          }
756: 
757:          current_ni = si_ni;
758:       }
759:       break;
760:       case TypeFloat:
761:       {
762:          // Convert child text (if any) to value, else default to 0.0
763:          double floatValue = 0.0;
764:          bool foundValue = false;
765: 
766:          if ( pi.childText.length() > 0 )
767:          {
768:             floatValue = strToDouble( pi.childText );
769:             foundValue = true;
770:          }
771: 
772:          std::shared_ptr<FloatNodeImpl> f_ni(
773:             new FloatNodeImpl( imf_, floatValue, pi.precision, pi.floatMinimum, pi.floatMaximum ) );
774: 
775:          if ( foundValue )
776:          {
777:             f_ni->validateValue();
778:          }
779: 
780:          current_ni = f_ni;
781:       }
782:       break;
783:       case TypeString:
784:       {
785:          std::shared_ptr<StringNodeImpl> s_ni( new StringNodeImpl( imf_, pi.childText ) );
786:          current_ni = s_ni;
787:       }
788:       break;
789:       case TypeBlob:
790:       {
791:          std::shared_ptr<BlobNodeImpl> b_ni( new BlobNodeImpl( imf_, pi.fileOffset, pi.length ) );
792:          current_ni = b_ni;
793:       }
794:       break;
795:       default:
796:          throw E57_EXCEPTION2(
797:             ErrorInternal, "nodeType=" + toString( pi.nodeType ) + " fileName=" + imf_->fileName() +
798:                               " uri=" + toUString( uri ) + " localName=" + toUString( localName ) +
799:                               " qName=" + toUString( qName ) );
800:    }
801: #ifdef E57_VERBOSE
802:    current_ni->dump( 4 );
803: #endif
804: 
805:    // If first node in file ended, we are all done
806:    if ( stack_.empty() )
807:    {
808:       // Top level should be Structure
809:       if ( current_ni->type() != TypeStructure )
810:       {
811:          throw E57_EXCEPTION2( ErrorBadXMLFormat, "currentType=" + toString( current_ni->type() ) +
812:                                                      " fileName=" + imf_->fileName() +
813:                                                      " uri=" + toUString( uri ) +
814:                                                      " localName=" + toUString( localName ) +
815:                                                      " qName=" + toUString( qName ) );
816:       }
817:       imf_->root_ = std::static_pointer_cast<StructureNodeImpl>( current_ni );
818:       return;
819:    }
820: 
821:    // Get next level up node (when entered function), which should be a container.
822:    NodeImplSharedPtr parent_ni = stack_.top().container_ni;
823: 
824:    if ( !parent_ni )
825:    {
826:       throw E57_EXCEPTION2( ErrorBadXMLFormat, "fileName=" + imf_->fileName() +
827:                                                   " uri=" + toUString( uri ) +
828:                                                   " localName=" + toUString( localName ) +
829:                                                   " qName=" + toUString( qName ) );
830:    }
831: 
832:    // Add current node into parent at top of stack
833:    switch ( parent_ni->type() )
834:    {
835:       case TypeStructure:
836:       {
837:          std::shared_ptr<StructureNodeImpl> struct_ni =
838:             std::static_pointer_cast<StructureNodeImpl>( parent_ni );
839: 
840:          // Add named child to structure
841:          struct_ni->set( toUString( qName ), current_ni );
842:       }
843:       break;
844:       case TypeVector:
845:       {
846:          std::shared_ptr<VectorNodeImpl> vector_ni =
847:             std::static_pointer_cast<VectorNodeImpl>( parent_ni );
848: 
849:          // Add unnamed child to vector
850:          vector_ni->append( current_ni );
851:       }
852:       break;
853:       case TypeCompressedVector:
854:       {
855:          std::shared_ptr<CompressedVectorNodeImpl> cv_ni =
856:             std::static_pointer_cast<CompressedVectorNodeImpl>( parent_ni );
857:          ustring uQName = toUString( qName );
858: 
859:          // n can be either prototype or codecs
860:          if ( uQName == "prototype" )
861:          {
862:             cv_ni->setPrototype( current_ni );
863:          }
864:          else if ( uQName == "codecs" )
865:          {
866:             if ( current_ni->type() != TypeVector )
867:             {
868:                throw E57_EXCEPTION2(
869:                   ErrorBadXMLFormat,
870:                   "currentType=" + toString( current_ni->type() ) +
871:                      " fileName=" + imf_->fileName() + " uri=" + toUString( uri ) +
872:                      " localName=" + toUString( localName ) + " qName=" + toUString( qName ) );
873:             }
874:             std::shared_ptr<VectorNodeImpl> vi =
875:                std::static_pointer_cast<VectorNodeImpl>( current_ni );
876: 
877:             // Check VectorNode is hetero
878:             if ( !vi->allowHeteroChildren() )
879:             {
880:                throw E57_EXCEPTION2(
881:                   ErrorBadXMLFormat,
882:                   "currentType=" + toString( current_ni->type() ) +
883:                      " fileName=" + imf_->fileName() + " uri=" + toUString( uri ) +
884:                      " localName=" + toUString( localName ) + " qName=" + toUString( qName ) );
885:             }
886: 
887:             cv_ni->setCodecs( vi );
888:          }
889:          else
890:          {
891:             // Found unknown XML child element of CompressedVector, not prototype or codecs
892:             throw E57_EXCEPTION2( ErrorBadXMLFormat, +"fileName=" + imf_->fileName() +
893:                                                         " uri=" + toUString( uri ) +
894:                                                         " localName=" + toUString( localName ) +
895:                                                         " qName=" + toUString( qName ) );
896:          }
897:       }
898:       break;
899:       default:
900:          // Have bad XML nesting, parent should have been a container.
901:          throw E57_EXCEPTION2( ErrorBadXMLFormat, "parentType=" + toString( parent_ni->type() ) +
902:                                                      " fileName=" + imf_->fileName() +
903:                                                      " uri=" + toUString( uri ) +
904:                                                      " localName=" + toUString( localName ) +
905:                                                      " qName=" + toUString( qName ) );
906:    }
